import SwiftUI
import AppKit

/// App logo embedded as a base64 PNG so it renders identically under
/// `swift run`, the .app bundle, and Xcode — no resource bundling needed.
enum AppLogo {
    static var image: Image? {
        guard let data = Data(base64Encoded: base64),
              let ns = NSImage(data: data) else { return nil }
        return Image(nsImage: ns)
    }

    // Single string literal (no + concatenation) to keep type-checking fast.
    private static let base64 = ""
}
